#include "cli.hpp"
namespace exotic::runtime {RuntimeCli::RuntimeCli(TelemetryRepository&r,std::string w,std::filesystem::path d):repo_(r),workspace_id_(std::move(w)),dashboard_(std::move(d)),control_(r,workspace_id_){}int RuntimeCli::run(const std::vector<std::string>&a,std::ostream&o){if(a.empty()||a[0]=="help"){o<<"runtime status|audit|alerts|dashboard|stop|emergency-stop|emergency-clear\n";return 0;}if(a[0]=="status"){o<<"EXOTIC CONTINUOUS OPERATIONS 1.0\nworkspace="<<workspace_id_<<"\n";for(auto&h:repo_.load_service_health())o<<h.service<<"  "<<to_string(h.state)<<"  "<<to_string(h.level)<<"  "<<h.message<<"\n";o<<"active_alerts="<<repo_.load_active_alerts().size()<<"\n";return 0;}if(a[0]=="audit"){for(auto&v:repo_.load_audit(50))o<<v.id<<"  "<<v.category<<"  "<<v.actor<<"  "<<v.message<<"\n";return 0;}if(a[0]=="alerts"){for(auto&v:repo_.load_active_alerts())o<<v.id<<"  "<<to_string(v.severity)<<"  "<<v.source<<"  "<<v.message<<"\n";return 0;}if(a[0]=="dashboard"){o<<dashboard_.json_path().string()<<"\n";return 0;}if(a[0]=="stop"){control_.request_shutdown("cli",a.size()>1?a[1]:"operator request");o<<"shutdown requested\n";return 0;}if(a[0]=="emergency-stop"){control_.request_emergency_stop("cli",a.size()>1?a[1]:"operator request");o<<"emergency stop requested\n";return 0;}if(a[0]=="emergency-clear"){control_.request_emergency_clear("cli",a.size()>1?a[1]:"operator request");o<<"emergency clear requested\n";return 0;}o<<"unknown runtime command\n";return 2;}}
